-- Backfill: the weekly schedules laid on the calendar, from the oldest
-- staff member's first day until 8 weeks ahead (store time, America/Lima),
-- so past absences and the coming weeks stay the same as before.
INSERT INTO "work_shifts" ("id_user", "work_date", "start_time", "end_time", "tolerance_min", "early_min", "color", "id_created_by", "id_updated_by")
SELECT ws."id_user", d.day::date, ws."start_time", ws."end_time", ws."tolerance_min", ws."early_min",
       CASE WHEN u."role" = 'warehouse' THEN '#1d4ed8' ELSE '#ea580c' END,
       ws."id_updated_by", ws."id_updated_by"
FROM "work_schedules" ws
JOIN "users" u ON u."id_user" = ws."id_user"
CROSS JOIN generate_series(
  (SELECT min((u2."created_at" AT TIME ZONE 'America/Lima')::date) FROM "users" u2),
  (now() AT TIME ZONE 'America/Lima')::date + 56,
  interval '1 day'
) AS d(day)
WHERE extract(dow FROM d.day)::int = ws."weekday"
  AND d.day::date >= (u."created_at" AT TIME ZONE 'America/Lima')::date
ON CONFLICT DO NOTHING;
